update public.products set description='Fresh sweet potato with naturally starchy, mildly sweet flesh suitable for boiling, frying, roasting, porridge, baking and other savoury or sweet preparations.', handling_protocols=array['Handle gently because cuts, abrasions and bruises shorten storage life.','Do not wash before storage; remove loose dry soil if needed and wash immediately before preparation.','Use damaged or cut roots first and keep sound roots dry and ventilated.']::text[], storage_tips=array['Keep in a cool, dark and well-ventilated place.','Do not refrigerate raw sweet potatoes for ordinary household storage because prolonged cold can cause chilling injury.','For best household quality, use within about 1–2 weeks after delivery.','Discard roots that become extensively soft, wet-rotten, moldy, leaking or strongly off-smelling.']::text[] where name='Sweet Potato' and category_id=(select id from public.product_categories where name='Tubers & Legumes');
update public.products set description='Fresh Irish potatoes with starchy tuber flesh suitable for boiling, frying, roasting, mashing, stews, porridge and a wide range of everyday meals.', handling_protocols=array['Handle gently and avoid cuts and bruising because damaged tubers decay more readily.','Do not wash before storage; brush away dry soil and wash immediately before cooking.','Remove sprouts before cooking and inspect tubers for green areas.']::text[], storage_tips=array['Store in a cool, dark, dry and well-ventilated place.','Protect completely from light because greening can be associated with increased glycoalkaloids.','For best household quality, use within about 1–2 weeks after delivery.','Do not use potatoes that are extensively green, strongly bitter, heavily rotten, very soft or extensively sprouted.']::text[] where name='Irish Potato' and category_id=(select id from public.product_categories where name='Tubers & Legumes');
update public.products set description='Fresh cocoyam with starchy corm flesh suitable for boiling, frying, porridge, soups and other traditional dishes, including use as a natural thickener in some soups.', handling_protocols=array['Handle carefully because cuts and bruises create entry points for decay.','Do not wash before storage; remove loose soil gently and wash immediately before preparation.','Keep corms dry and ventilated and use damaged pieces first.','Cook cocoyam properly before eating rather than consuming it raw.']::text[], storage_tips=array['Store whole cocoyam in a cool, shaded, dry and well-ventilated place away from damp floors.','Do not seal damp cocoyam in airtight plastic.','For dependable household quality, use within about 1–2 weeks after delivery.','Discard corms that become soft, slimy, moldy, leaking or strongly rotten-smelling.']::text[] where name='Cocoyam' and category_id=(select id from public.product_categories where name='Tubers & Legumes');;
